package com.example.payment.application.order;

import com.example.payment.domain.order.Order;

/** Consults and cancels orders on behalf of their owner; other customers' orders look nonexistent. */
public final class OrderService {

    private final OrderRepository orders;

    public OrderService(OrderRepository orders) {
        this.orders = orders;
    }

    public Order get(String customerId, String orderId) {
        return orders.findById(orderId)
                .filter(order -> order.belongsTo(customerId))
                .orElseThrow(() -> new OrderNotFoundException(orderId));
    }

    public Order cancel(String customerId, String orderId) {
        var order = get(customerId, orderId);
        order.cancel();
        orders.save(order);
        return order;
    }
}
