package com.example.payment.app;

import com.example.payment.application.order.OrderNotFoundException;
import com.example.payment.application.order.OrderService;
import com.example.payment.domain.order.Order;
import com.example.payment.domain.order.OrderNotCancellableException;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
class OrderController {

    record OrderResponse(String id, String status) {}

    private final OrderService orders;

    OrderController(OrderService orders) {
        this.orders = orders;
    }

    @GetMapping("/orders/{id}")
    OrderResponse get(@RequestHeader("X-Customer-Id") String customerId, @PathVariable String id) {
        return toResponse(orders.get(customerId, id));
    }

    @PostMapping("/orders/{id}/cancel")
    OrderResponse cancel(@RequestHeader("X-Customer-Id") String customerId, @PathVariable String id) {
        return toResponse(orders.cancel(customerId, id));
