package com.example.payment.domain.order;

import java.util.Objects;

/** An order placed by a customer; it can be cancelled only while pending. */
public final class Order {

    private final String id;
    private final String customerId;
    private OrderStatus status = OrderStatus.PENDING;

    public Order(String id, String customerId) {
        this.id = Objects.requireNonNull(id);
        this.customerId = Objects.requireNonNull(customerId);
    }

    public String id() { return id; }

    public String customerId() { return customerId; }

    public synchronized OrderStatus status() { return status; }

    public boolean belongsTo(String customerId) { return this.customerId.equals(customerId); }

    public synchronized void cancel() {
        if (status != OrderStatus.PENDING) throw new OrderNotCancellableException(id);
        status = OrderStatus.CANCELLED;
    }
}
